package com.example.spinach

import com.google.android.gms.tasks.Task
import com.google.android.gms.tasks.Tasks
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.WriteBatch

//This code was partly generated by Claude Sonnet 5.5, 5/11/2026 over the prompt "How do I integrate this class with Firebase? (with given context by attaching files)"


/**
* Handles saving, loading, and deleting [User] objects in Cloud Firestore.
*
* Keeps all database code out of the [User] model. Each user is stored as one
* document in the [COLLECTION] collection, with the user's [User.id] as the
* document ID (so `users/{id}`). Passwords are not stored here, see [AccountRepository].
*
* All functions return a [Task], so the caller decides how to react:
* ```
* repository.get(id)
*     .addOnSuccessListener { user -> ... }   // user is null if no such document
*     .addOnFailureListener { e -> ... }
* ```
*
* Note: Firestore only completes a write [Task] once the server confirms it. While
* the device is offline the write is queued locally, but the task stays pending
* until the connection returns.
*
* Covers: US 01.09.01, US 01.07.03, US 01.08.01, US 01.10.01 (persistence of the
* data those stories manage), and the profile browsing/removal needed by
* US 03.02.01 and US 03.05.01.
*
* Collaborators (currently stubbed): Reservation, Lottery, Notification, Message,
* used when cleaning up a deleted user's related data.
*
* @param db The Firestore instance to use. Defaults to the app-wide instance;
* pass a different one in tests.
*/

class UserRepository(private val db: FirebaseFirestore = FirebaseFirestore.getInstance()) {
    private val users = db.collection(COLLECTION)

    /**
     * Saves a user, creating the document if it doesn't exist or fully replacing
     * it if it does. Use this for both first-time creation and later profile edits.
     *
     * @param user The user to store. Its [User.id] must not be blank.
     * @return A task that completes when the write is confirmed. Fails with an
     * [IllegalArgumentException] if the ID is blank.
     */
    fun save(user: User): Task<Void> {
        if (user.id.isBlank()) {
            return Tasks.forException(IllegalArgumentException("User has no id"))
        }
        return users.document(user.id).set(user)
    }

    /**
     * Loads one user.
     *
     * @param userId The user's ID.
     * @return A task whose result is the [User], or `null` if no user with that
     * ID is stored. Fails with an [IllegalArgumentException] if [userId] is blank.
     */
    fun get(userId: String): Task<User?> {
        if (userId.isBlank()) {
            return Tasks.forException(IllegalArgumentException("userId is blank"))
        }
        return users.document(userId).get().continueWith { task ->
            task.result?.toObject(User::class.java)
        }
    }

    /**
     * Checks whether a user is stored, without building a [User] object.
     *
     * @param userId The user's ID.
     * @return A task whose result is `true` if the document exists.
     */
    fun exists(userId: String): Task<Boolean> {
        if (userId.isBlank()) {
            return Tasks.forException(IllegalArgumentException("userId is blank"))
        }
        return users.document(userId).get().continueWith { task ->
            task.result?.exists() == true
        }
    }

    /**
     * Permanently deletes a user's document (US 01.08.01).
     *
     * Before a user's document is removed:
     * - deletes the notifications the user received
     * - cancels the user's ACTIVE reservations (status becomes CANCELLED, so owners keep their history)
     * - removes the user from every lottery waitlist, winners list and losers list
     * - for campsites the user owns: deletes the campsites and their lotteries, and cancels the ACTIVE reservations made at them
     *
     * Notifications the user sent are kept so admins can still review them
     * (US 03.08.01). Campsite images in Firebase Storage are not touched (to do).
     *
     * Deleting a user that doesn't exist still succeeds. After this, discard the
     * in-memory [User] object. [User.clearProfile] only wipes the object and does
     * not touch the database.
     *
     * Also usable by an admin to remove a profile (US 03.02.01, US 03.05.01).
     *
     * @param userId The ID of the user to delete.
     * @return A task that completes when the delete is confirmed.
     */
    fun delete(userId: String): Task<Void> {
        if (userId.isBlank()) {
            return Tasks.forException(IllegalArgumentException("userId is blank"))
        }

        // Read everything that refers to this user.
        val receivedNotifications =
            db.collection(NOTIFICATIONS).whereEqualTo("recipientId", userId).get()
        val ownReservations =
            db.collection(RESERVATIONS).whereEqualTo("entrantId", userId).get()
        val reservationsAtOwnCampsites =
            db.collection(RESERVATIONS).whereEqualTo("ownerId", userId).get()
        val onWaitlist =
            db.collection(LOTTERIES).whereArrayContains("waitlist", userId).get()
        val asWinner =
            db.collection(LOTTERIES).whereArrayContains("winners", userId).get()
        val asLoser =
            db.collection(LOTTERIES).whereArrayContains("losers", userId).get()
        val ownedLotteries =
            db.collection(LOTTERIES).whereEqualTo("ownerId", userId).get()
        val ownedCampsites =
            db.collection(CAMPSITES).whereEqualTo("ownerId", userId).get()

        return Tasks.whenAll(receivedNotifications, ownReservations, reservationsAtOwnCampsites, onWaitlist, asWinner, asLoser, ownedLotteries, ownedCampsites
        ).continueWithTask<Void> { readsTask ->
            readsTask.result // throws if any read failed, so nothing gets written

            val updates = mutableListOf<(WriteBatch) -> Unit>()
            val deletes = mutableListOf<(WriteBatch) -> Unit>()

            // Cancel ACTIVE reservations, both the user's own and those at their campsites.
            // The set stops a reservation in both groups from being updated twice.
            val cancelled = mutableSetOf<String>()
            for (snapshot in listOf(ownReservations.result, reservationsAtOwnCampsites.result)) {
                for (doc in snapshot.documents) {
                    val isActive = doc.getString("status") == ReservationStatus.ACTIVE.name
                    if (isActive && cancelled.add(doc.reference.path)) {
                        updates.add {
                            it.update(doc.reference, "status", ReservationStatus.CANCELLED.name)
                        }
                    }
                }
            }

            // Take the user out of other owners' lotteries. Lotteries the user owns are
            // deleted below, so they are skipped here.
            val ownedLotteryIds = ownedLotteries.result.documents.map { it.id }.toSet()
            val removals = listOf(
                "waitlist" to onWaitlist.result,
                "winners" to asWinner.result,
                "losers" to asLoser.result
            )
            for ((field, snapshot) in removals) {
                for (doc in snapshot.documents) {
                    if (doc.id !in ownedLotteryIds) {
                        updates.add {
                            it.update(doc.reference, field, FieldValue.arrayRemove(userId))
                        }
                    }
                }
            }

            // Delete the notifications received, the lotteries owned, and the campsites owned.
            for (snapshot in listOf(
                receivedNotifications.result,
                ownedLotteries.result,
                ownedCampsites.result
            )) {
                for (doc in snapshot.documents) {
                    deletes.add { it.delete(doc.reference) }
                }
            }

            commitAll(updates + deletes)
        }.continueWithTask<Void> { cleanupTask ->
            cleanupTask.result // throws if the cleanup failed, so the user document is kept
            users.document(userId).delete()
        }
    }
    /**
     * Runs the given writes in batches. Firestore allows at most 500 writes per batch,
     * so they are split into chunks of [BATCH_SIZE]. An empty list completes immediately.
     */
    private fun commitAll(operations: List<(WriteBatch) -> Unit>): Task<Void> {
        val commits = operations.chunked(BATCH_SIZE).map { chunk ->
            val batch = db.batch()
            chunk.forEach { operation -> operation(batch) }
            batch.commit()
        }
        return Tasks.whenAll(commits)
    }

    /**
     * Loads every stored user, for admin browsing (US 03.02.01).
     *
     * @return A task whose result is all users, in no particular order.
     */
    fun getAll(): Task<List<User>> {
        return users.get().continueWith { task ->
            task.result.toObjects(User::class.java)
        }
    }

    // ------------------------------------------------------ collaborator lookups

    /**
     * Loads the notifications this user has received (US 01.03.01, US 01.03.02).
     * Matches [Notification.recipientId].
     *
     * @param userId The user's ID.
     * @return A task whose result is the matching notifications, in no particular order.
     */
    fun getNotifications(userId: String): Task<List<Notification>> =
        findByField(NOTIFICATIONS, "recipientId", userId, Notification::class.java)

    /**
     * Loads the notifications this user has sent, for owners (US 02.10.02).
     * Matches [Notification.senderId].
     *
     * @param userId The user's ID.
     * @return A task whose result is the matching notifications, in no particular order.
     */
    fun getSentNotifications(userId: String): Task<List<Notification>> =
        findByField(NOTIFICATIONS, "senderId", userId, Notification::class.java)

    /**
     * Loads every reservation this user has made as an entrant, whatever its status
     * (US 01.06.01, US 01.06.02). Matches [Reservation.entrantId].
     *
     * To split the result into active and past, use
     * `ReservationQueries.active(list, ReservationQueries.todayUtcMidnight())` and
     * `ReservationQueries.past(...)`.
     *
     * @param userId The user's ID.
     * @return A task whose result is the matching reservations, in no particular order.
     */
    fun getReservations(userId: String): Task<List<Reservation>> =
        findByField(RESERVATIONS, "entrantId", userId, Reservation::class.java)

    /**
     * Loads the lotteries whose waitlist currently contains this user
     * (US 01.02.01, US 01.02.02). Matches [Lottery.waitlist].
     *
     * Note that [Lottery.draw] empties the waitlist, so once a lottery is drawn the
     * user moves to its winners or losers list and no longer appears here.
     *
     * @param userId The user's ID.
     * @return A task whose result is the matching lotteries, in no particular order.
     */
    fun getJoinedLotteries(userId: String): Task<List<Lottery>> {
        if (userId.isBlank()) {
            return Tasks.forException(IllegalArgumentException("userId is blank"))
        }
        return db.collection(LOTTERIES).whereArrayContains("waitlist", userId).get()
            .continueWith<List<Lottery>> { task -> task.result.toObjects(Lottery::class.java) }
    }

    /**
     * Loads the campsites this user owns (US 02.03.01). Matches [Campsite.ownerId].
     *
     * Unlike CampsiteRepository.ownerCampsites, this works for any user ID, not just
     * the signed-in one, and is a one-time read rather than a live listener.
     *
     * @param userId The user's ID.
     * @return A task whose result is the matching campsites, in no particular order.
     */
    fun getOwnedCampsites(userId: String): Task<List<Campsite>> =
        findByField(CAMPSITES, "ownerId", userId, Campsite::class.java)

    /** Queries [collection] for documents whose [field] equals [value]. */
    private fun <T : Any> findByField(
        collection: String,
        field: String,
        value: String,
        type: Class<T>
    ): Task<List<T>> {
        if (value.isBlank()) {
            return Tasks.forException(IllegalArgumentException("userId is blank"))
        }
        return db.collection(collection).whereEqualTo(field, value).get()
            .continueWith { task -> task.result.toObjects(type) }
    }

    companion object {
        /** Name of the Firestore collection that holds user documents. */
        const val COLLECTION = "users"
        private const val BATCH_SIZE = 200

        // Same collection names the other repositories use.
        private const val NOTIFICATIONS = "notifications"
        private const val RESERVATIONS = "reservations"
        private const val LOTTERIES = "lotteries"
        private const val CAMPSITES = "campsites"
    }
}